"use client";

import { ReactNode, useEffect, useMemo, useState } from "react";
import { FABLE_CARD_BACKS, cardFrontArt, mapArt } from "@/lib/fableFuryAssets";
import { FABLE_BACKPACK_ART, FABLE_BOARD_ART, FABLE_SHOP_ART, FABLE_STAT_ART, FABLE_TOKEN_ART } from "@/lib/fableFuryBoardAssets";
import { FABLE_HEROES, TOKEN_LABELS, getHero, type SkillColor, type TokenKind } from "@/lib/fableFuryHeroes";
import { getEventPlan, requirementMet, type EventEffect, type EventPlan } from "@/lib/fableFuryEventEngine";
import { getLootPlan, type LootContext, type LootEffect } from "@/lib/fableFuryLootEngine";

type FableCard = {
  id: string;
  card_type: "loot" | "event" | "trap" | "enemy" | "special" | "skill" | "monster" | "hero";
  title: string;
  subtype?: string | null;
  difficulty?: string | null;
  race?: string | null;
  rules_text?: string | null;
  story_text?: string | null;
  source_sheet?: string | null;
  source_row?: number | null;
  data?: Record<string, unknown> | null;
};

type MapInfo = { id: string; name: string; start_cell: string; grid: { rows: number; columns: string[]; active_cells: string[] } };
type RunSetup = { run_id: string; realm: number; maps: MapInfo[]; deck_counts: Record<string, number> };
type RevealResult = { cell: string; already_revealed: boolean; card: FableCard; map: MapInfo; revealed: string[] };
type GamePhase = "hero" | "gear" | "realm";
type EventStatus = "pending" | "resolving" | "resolved";
type RollMode = "roll" | "pickNumber" | "optionalRoll";
type EventState = { key: string; plan: EventPlan; status: EventStatus; messages: string[]; roll?: number; rollMode?: RollMode; pick?: number };
type TokenCounts = Record<TokenKind, number>;
type LootUse = { slot: number; card: FableCard };
type QueuedDamage = { source: string; amount: number; targetRace?: string; targetRaceAmount?: number; everyone?: boolean };
type CombatMods = { attackDiceBonus: number; attackRollBonus: number; rerollAttack: boolean; targeting: "anyHero" | "self" | null; enemyDamageDelta: number; enemyAgilityDelta: number; rewardBonus: number };
type SkillDraft = { mode: "shrine" | "replace"; color: SkillColor | "any"; choices: FableCard[]; slot?: number; sourceKey?: string; title: string; stage: "slot" | "color" | "choices" };

const REALM_RECIPES: Record<number, string> = { 1: "1 Portal · 1 Shrine · 1 Trap · 4 Easy Enemies · 7 Events", 2: "1 Portal · 1 Shrine · 2 Traps · 4 Medium Enemies · 6 Events", 3: "1 Portal · 1 Shrine · 3 Traps · 4 Hard Enemies · 5 Events" };
const EMPTY_TOKENS: TokenCounts = { healing: 0, lucky: 0, crystal: 0 };
const SKILL_COLORS: SkillColor[] = ["red", "blue", "green", "yellow"];
const EMPTY_COMBAT_MODS: CombatMods = { attackDiceBonus: 0, attackRollBonus: 0, rerollAttack: false, targeting: null, enemyDamageDelta: 0, enemyAgilityDelta: 0, rewardBonus: 0 };

function clamp(value: number, min: number, max: number) { return Math.min(max, Math.max(min, value)); }
function totalCoins(slots: number[]) { return slots.reduce((sum, value) => sum + value, 0); }
function isAdjacent(a: string, b: string) { const ax = a.charCodeAt(0) - 65; const ay = Number(a.slice(1)); const bx = b.charCodeAt(0) - 65; const by = Number(b.slice(1)); return Math.abs(ax - bx) + Math.abs(ay - by) === 1; }
function boardCellPosition(cell: string) { const columnIndex = cell.charCodeAt(0) - 65; const rowIndex = Number(cell.slice(1)) - 1; return { left: `${16.45 + columnIndex * 12.86}%`, top: `${19.45 + rowIndex * 16.12}%` }; }
function displayCardType(card: FableCard) { return card.data?.digital_card_type === "trap" ? "trap" : card.card_type; }

async function postJson<T>(url: string, body: unknown): Promise<T> {
  const response = await fetch(url, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
  const data = await response.json();
  if (!response.ok) throw new Error(data?.error || "Request failed");
  return data as T;
}

function adjustCoinSlots(current: number[], loot: Array<FableCard | null>, delta: number) {
  const next = [...current]; let remaining = Math.abs(delta);
  if (delta >= 0) {
    for (let index = 0; index < next.length && remaining > 0; index += 1) { if (next[index] <= 0) continue; const room = 6 - next[index]; const add = Math.min(room, remaining); next[index] += add; remaining -= add; }
    for (let index = 0; index < next.length && remaining > 0; index += 1) { if (next[index] > 0 || loot[index]) continue; const add = Math.min(6, remaining); next[index] = add; remaining -= add; }
    return { slots: next, applied: delta - remaining, overflow: remaining };
  }
  for (let index = next.length - 1; index >= 0 && remaining > 0; index -= 1) { if (next[index] <= 0) continue; const remove = Math.min(next[index], remaining); next[index] -= remove; remaining -= remove; }
  return { slots: next, applied: -(Math.abs(delta) - remaining), overflow: 0 };
}

function CardImage({ card, className = "" }: { card: FableCard; className?: string }) {
  const src = cardFrontArt(card);
  if (!src) return <div className={`grid place-items-center rounded-2xl border border-white/10 bg-[#151b25] p-4 text-center ${className}`}><div><div className="text-[9px] font-black uppercase tracking-[.16em] text-amber-300">{displayCardType(card)}</div><div className="mt-2 text-lg font-black">{card.title}</div>{card.rules_text && <p className="mt-3 text-xs leading-5 text-white/55">{card.rules_text}</p>}</div></div>;
  return <img src={src} alt={card.title} className={`block object-contain ${className}`} />;
}

function FlipCard({ card, back }: { card: FableCard; back: string }) {
  const [faceUp, setFaceUp] = useState(false); const front = cardFrontArt(card);
  useEffect(() => { setFaceUp(false); const timer = window.setTimeout(() => setFaceUp(true), 100); return () => window.clearTimeout(timer); }, [card.id]);
  return <div className="mx-auto w-full max-w-[420px] [perspective:1400px]"><div className="relative aspect-[746/1039] w-full" style={{ transformStyle: "preserve-3d", transform: faceUp ? "rotateY(180deg)" : "rotateY(0deg)", transition: "transform 650ms cubic-bezier(.2,.72,.18,1)" }}><img src={back} alt="Card back" className="absolute inset-0 h-full w-full rounded-[24px] object-cover shadow-[0_35px_90px_rgba(0,0,0,.55)]" style={{ backfaceVisibility: "hidden" }} /><div className="absolute inset-0 overflow-hidden rounded-[24px] bg-[#111821] shadow-[0_35px_90px_rgba(0,0,0,.55)]" style={{ backfaceVisibility: "hidden", transform: "rotateY(180deg)" }}>{front ? <img src={front} alt={card.title} className="h-full w-full object-cover" /> : <CardImage card={card} className="h-full w-full" />}</div></div></div>;
}

function StatPill({ art, label, value, max }: { art: string; label: string; value: number; max?: number }) {
  return <div className="flex min-w-0 items-center gap-2 rounded-2xl border border-white/10 bg-black/25 px-3 py-2"><img src={art} alt="" className="h-8 w-8 shrink-0 object-contain" /><div className="min-w-0"><div className="truncate text-[9px] font-black uppercase tracking-[.12em] text-white/35">{label}</div><div className="mt-0.5 text-lg font-black text-[#fff4d8]">{value}{typeof max === "number" ? <span className="text-xs text-white/30">/{max}</span> : null}</div></div></div>;
}
function MiniStat({ art, value }: { art: string; value: number }) { return <span className="inline-flex items-center gap-1.5"><img src={art} alt="" className="h-5 w-5 object-contain" /><strong>{value}</strong></span>; }

function TokenAction({ token, count, disabled, onUse, compact = false }: { token: TokenKind; count: number; disabled?: boolean; onUse: () => void; compact?: boolean }) {
  const descriptions: Record<TokenKind, string> = { healing: "+1 Health", crystal: "Reveal any Location", lucky: "Reroll a die" };
  return <button type="button" onClick={onUse} disabled={disabled || count <= 0} className={`group relative flex items-center gap-2 rounded-2xl border border-white/10 bg-black/25 text-left transition hover:border-amber-300/40 hover:bg-amber-300/10 disabled:cursor-not-allowed disabled:opacity-35 ${compact ? "px-2.5 py-2" : "px-3 py-3"}`} title={`${TOKEN_LABELS[token]}: ${descriptions[token]}`}><div className="relative shrink-0"><img src={FABLE_TOKEN_ART[token]} alt={TOKEN_LABELS[token]} className={`${compact ? "h-9 w-9" : "h-12 w-12"} object-contain drop-shadow-lg`} /><span className="absolute -right-1 -top-1 grid h-5 min-w-5 place-items-center rounded-full bg-amber-300 px-1 text-[10px] font-black text-[#241707]">{count}</span></div>{!compact && <div className="min-w-0"><strong className="block truncate text-xs text-[#fff4d8]">{TOKEN_LABELS[token]}</strong><span className="mt-0.5 block truncate text-[10px] text-white/40">{descriptions[token]}</span></div>}</button>;
}

function BackpackPanel({ backpack, coinSlots, tokens, onUseToken, onUseLoot, luckyDisabled, crystalDisabled }: { backpack: Array<FableCard | null>; coinSlots: number[]; tokens: TokenCounts; onUseToken: (token: TokenKind) => void; onUseLoot: (slot: number) => void; luckyDisabled?: boolean; crystalDisabled?: boolean }) {
  const tokenSlots: Array<{ token: TokenKind; left: string }> = [{ token: "lucky", left: "17%" }, { token: "crystal", left: "50%" }, { token: "healing", left: "83%" }]; const lootLeft = ["17%", "50%", "83%"];
  return <div className="rounded-[24px] border border-white/10 bg-white/[.035] p-4"><div className="flex items-end justify-between gap-3"><div><div className="text-[9px] font-black uppercase tracking-[.14em] text-amber-300">Backpack</div><div className="mt-0.5 text-sm font-black">Tokens + Loot can be used any time</div></div><div className="text-[9px] text-white/30">Click an item to use it</div></div><div className="relative mt-3 aspect-[3/2] overflow-hidden rounded-2xl border border-white/10 bg-[#7ca5c1]/15"><img src={FABLE_BACKPACK_ART} alt="Fable Fury Backpack" className="absolute inset-0 h-full w-full object-cover" />{tokenSlots.map(({ token, left }) => <button key={token} type="button" disabled={tokens[token] <= 0 || (token === "lucky" && luckyDisabled) || (token === "crystal" && crystalDisabled)} onClick={() => onUseToken(token)} className="absolute top-[18%] z-10 w-[18%] -translate-x-1/2 transition hover:scale-110 disabled:opacity-30" style={{ left }}>{tokens[token] > 0 && <img src={FABLE_TOKEN_ART[token]} alt={TOKEN_LABELS[token]} className="w-full object-contain drop-shadow-[0_8px_8px_rgba(0,0,0,.45)]" />}<span className="absolute -right-1 top-0 grid h-5 min-w-5 place-items-center rounded-full bg-[#fff1bf] px-1 text-[10px] font-black text-[#40220f]">{tokens[token]}</span></button>)}{lootLeft.map((left, index) => <div key={left} className="absolute top-[53%] z-10 flex h-[35%] w-[20%] -translate-x-1/2 items-center justify-center" style={{ left }}>{backpack[index] ? <button type="button" onClick={() => onUseLoot(index)} className="group relative max-h-full max-w-full transition hover:scale-110"><CardImage card={backpack[index] as FableCard} className="max-h-full max-w-full rounded-lg drop-shadow-[0_8px_8px_rgba(0,0,0,.5)]" /><span className="absolute inset-x-1 bottom-1 rounded bg-amber-300/95 py-1 text-center text-[7px] font-black uppercase tracking-[.12em] text-[#241707] opacity-0 transition group-hover:opacity-100">Use</span></button> : coinSlots[index] > 0 ? <div className="relative flex h-full w-full items-center justify-center"><img src={FABLE_STAT_ART.coins} alt="Coins" className="w-[70%] object-contain drop-shadow-lg" /><span className="absolute bottom-0 right-0 grid h-7 min-w-7 place-items-center rounded-full bg-amber-300 px-1 text-xs font-black text-[#3a2109]">{coinSlots[index]}</span></div> : <span className="rounded-full bg-black/35 px-2 py-1 text-[9px] font-black uppercase tracking-[.1em] text-white/45">Empty</span>}</div>)}</div><div className="mt-3 grid grid-cols-3 gap-2"><TokenAction token="lucky" count={tokens.lucky} onUse={() => onUseToken("lucky")} disabled={luckyDisabled} compact /><TokenAction token="crystal" count={tokens.crystal} onUse={() => onUseToken("crystal")} disabled={crystalDisabled} compact /><TokenAction token="healing" count={tokens.healing} onUse={() => onUseToken("healing")} compact /></div></div>;
}

function ModalShell({ children, z = "z-[250]" }: { children: ReactNode; z?: string }) { return <div className={`fixed inset-0 ${z} grid place-items-center overflow-y-auto bg-[#05070b]/90 p-4 py-8 backdrop-blur-xl`}>{children}</div>; }

export default function FableFurySoloRun() {
  const [phase, setPhase] = useState<GamePhase>("hero"); const [heroId, setHeroId] = useState(FABLE_HEROES[0].id); const [startingToken, setStartingToken] = useState<TokenKind | null>(null); const hero = useMemo(() => getHero(heroId), [heroId]);
  const [health, setHealth] = useState(hero.startingHealth); const [armor, setArmor] = useState(hero.startingArmor); const [attackDice, setAttackDice] = useState(hero.startingAttackDice); const [coinSlots, setCoinSlots] = useState([0, 0, 0]); const coins = totalCoins(coinSlots); const [tokens, setTokens] = useState<TokenCounts>({ ...EMPTY_TOKENS }); const [backpack, setBackpack] = useState<Array<FableCard | null>>([null, null, null]); const [lootInbox, setLootInbox] = useState<FableCard[]>([]); const [lootDiscard, setLootDiscard] = useState<FableCard[]>([]);
  const [skills, setSkills] = useState<Array<FableCard | null>>([null, null, null]); const [skillDraft, setSkillDraft] = useState<SkillDraft | null>(null);
  const [run, setRun] = useState<RunSetup | null>(null); const [realm, setRealm] = useState(1); const [revealed, setRevealed] = useState<Record<number, string[]>>({ 1: [], 2: [], 3: [] }); const [cardsByCell, setCardsByCell] = useState<Record<string, FableCard>>({}); const [scoutedByCell, setScoutedByCell] = useState<Record<string, FableCard>>({}); const [scoutRemaining, setScoutRemaining] = useState(0); const [selectedCard, setSelectedCard] = useState<FableCard | null>(null); const [selectedCell, setSelectedCell] = useState<string | null>(null); const [showReveal, setShowReveal] = useState(false);
  const [lootRemaining, setLootRemaining] = useState(60); const [skillRemaining, setSkillRemaining] = useState<Record<SkillColor, number>>({ red: 18, blue: 18, green: 18, yellow: 18 }); const [eventState, setEventState] = useState<EventState | null>(null); const [resolvedEncounterKeys, setResolvedEncounterKeys] = useState<string[]>([]); const [encounterHistory, setEncounterHistory] = useState<Record<string, string[]>>({}); const [resolvedSpecialKeys, setResolvedSpecialKeys] = useState<string[]>([]); const [specialHistory, setSpecialHistory] = useState<Record<string, string[]>>({}); const [shrineStartedKeys, setShrineStartedKeys] = useState<string[]>([]);
  const [lootUse, setLootUse] = useState<LootUse | null>(null); const [queuedDamage, setQueuedDamage] = useState<QueuedDamage[]>([]); const [combatMods, setCombatMods] = useState<CombatMods>({ ...EMPTY_COMBAT_MODS });
  const [loading, setLoading] = useState<string | null>(null); const [error, setError] = useState<string | null>(null); const [toast, setToast] = useState<string | null>(null);

  const map = run?.maps[realm - 1] ?? null; const mapImage = mapArt(map?.id); const realmRevealed = revealed[realm] ?? []; const remainingLocations = 14 - realmRevealed.length; const pendingRoll = eventState?.status === "pending" && typeof eventState.roll === "number"; const shrinePending = skillDraft?.mode === "shrine"; const inventoryLocked = lootInbox.length > 0; const encounterLocked = eventState?.status === "pending" || eventState?.status === "resolving" || shrinePending;

  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(null), 2800); return () => window.clearTimeout(timer); }, [toast]);
  function notify(message: string) { setToast(message); }
  function eventContext(overrides?: Partial<{ health: number; armor: number; attackDice: number; coins: number; backpack: Array<FableCard | null> }>) { const useBackpack = overrides?.backpack ?? backpack; return { health: overrides?.health ?? health, armor: overrides?.armor ?? armor, attackDice: overrides?.attackDice ?? attackDice, coins: overrides?.coins ?? coins, lootCount: useBackpack.filter(Boolean).length, lootNames: useBackpack.flatMap((card) => card ? [card.title] : []) }; }
  function lootContext(): LootContext { return { race: hero.race, health, maxHealth: hero.maxHealth, armor, maxArmor: hero.maxArmor, attackDice, maxAttackDice: hero.maxAttackDice, coins, hasCoreRoll: pendingRoll, trapPending: Boolean(eventState?.status === "pending" && selectedCard?.data?.digital_card_type === "trap"), skillCount: skills.filter(Boolean).length }; }

  function resetAdventure() { setPhase("hero"); setRun(null); setStartingToken(null); setHealth(hero.startingHealth); setArmor(hero.startingArmor); setAttackDice(hero.startingAttackDice); setCoinSlots([0, 0, 0]); setTokens({ ...EMPTY_TOKENS }); setBackpack([null, null, null]); setLootInbox([]); setLootDiscard([]); setSkills([null, null, null]); setSkillDraft(null); setRealm(1); setRevealed({ 1: [], 2: [], 3: [] }); setCardsByCell({}); setScoutedByCell({}); setScoutRemaining(0); setSelectedCard(null); setSelectedCell(null); setShowReveal(false); setEventState(null); setResolvedEncounterKeys([]); setEncounterHistory({}); setResolvedSpecialKeys([]); setSpecialHistory({}); setShrineStartedKeys([]); setQueuedDamage([]); setCombatMods({ ...EMPTY_COMBAT_MODS }); setError(null); }

  async function drawLootCards(runId: string, count: number) { const cards: FableCard[] = []; let remaining = lootRemaining; for (let index = 0; index < count; index += 1) { const result = await postJson<{ card: FableCard | null; remaining: number }>("/api/fablefury/draw", { runId, deckKey: "loot" }); if (result.card) cards.push(result.card); remaining = result.remaining; } setLootRemaining(remaining); if (cards.length) setLootInbox((current) => [...current, ...cards]); return cards; }
  async function drawSkillCards(color: SkillColor, count = 3) { if (!run) return []; const cards: FableCard[] = []; let remaining = skillRemaining[color]; for (let index = 0; index < count; index += 1) { const result = await postJson<{ card: FableCard | null; remaining: number }>("/api/fablefury/draw", { runId: run.run_id, deckKey: `skills-${color}` }); if (result.card) cards.push(result.card); remaining = result.remaining; } setSkillRemaining((current) => ({ ...current, [color]: remaining })); return cards; }

  async function lockHeroAndDeal() { if (!startingToken) return; setLoading("setup"); setError(null); try { const setup = await postJson<RunSetup>("/api/fablefury/run", { heroIds: [hero.id] }); setRun(setup); setRealm(1); setRevealed({ 1: [], 2: [], 3: [] }); setCardsByCell({}); setScoutedByCell({}); setResolvedEncounterKeys([]); setEncounterHistory({}); setResolvedSpecialKeys([]); setSpecialHistory({}); setShrineStartedKeys([]); setHealth(hero.startingHealth); setArmor(hero.startingArmor); setAttackDice(hero.startingAttackDice); setCoinSlots([2, 0, 0]); setTokens({ ...EMPTY_TOKENS, [startingToken]: 1 }); setBackpack([null, null, null]); setLootInbox([]); setLootDiscard([]); setSkills([null, null, null]); setQueuedDamage([]); setCombatMods({ ...EMPTY_COMBAT_MODS }); setLootRemaining(setup.deck_counts.loot ?? 60); setSkillRemaining({ red: setup.deck_counts["skills-red"] ?? 18, blue: setup.deck_counts["skills-blue"] ?? 18, green: setup.deck_counts["skills-green"] ?? 18, yellow: setup.deck_counts["skills-yellow"] ?? 18 }); const result = await postJson<{ card: FableCard | null; remaining: number }>("/api/fablefury/draw", { runId: setup.run_id, deckKey: "loot" }); if (result.card) setLootInbox([result.card]); setLootRemaining(result.remaining); setPhase("gear"); } catch (err) { setError(err instanceof Error ? err.message : "Could not create the solo run."); } finally { setLoading(null); } }

  function packLoot(inboxIndex: number, slot: number) { const card = lootInbox[inboxIndex]; if (!card || coinSlots[slot] > 0 || backpack[slot]) return; setBackpack((current) => current.map((item, index) => index === slot ? card : item)); setLootInbox((current) => current.filter((_, index) => index !== inboxIndex)); }
  function discardInboxLoot(inboxIndex: number) { const card = lootInbox[inboxIndex]; if (!card) return; setLootDiscard((current) => [...current, card]); setLootInbox((current) => current.filter((_, index) => index !== inboxIndex)); }

  function useToken(token: TokenKind) { if (tokens[token] <= 0) return; if (token === "healing") { if (health >= hero.maxHealth) { notify(`${hero.name} is already at full Health.`); return; } setTokens((current) => ({ ...current, healing: current.healing - 1 })); setHealth((current) => Math.min(hero.maxHealth, current + 1)); notify(`Healing Potion used — ${hero.name} gains 1 Health.`); return; } if (token === "crystal") { if (!run || phase !== "realm") { notify("Enter a Realm before using a Crystal Ball."); return; } setTokens((current) => ({ ...current, crystal: current.crystal - 1 })); setScoutRemaining((current) => current + 1); notify("Crystal Ball used — choose any unexplored Location."); return; } if (!pendingRoll) { notify("Lucky Charm is ready when you have a die result to reroll."); return; } setTokens((current) => ({ ...current, lucky: current.lucky - 1 })); const reroll = Math.floor(Math.random() * 6) + 1; setEventState((current) => current ? { ...current, roll: reroll } : current); notify(`Lucky Charm used — rerolled to ${reroll}.`); }

  async function applyEffects(effects: EventEffect[], sourceKey: string) { let nextHealth = health; let nextArmor = armor; let nextAttackDice = attackDice; let nextTokens = { ...tokens }; let nextBackpack = [...backpack]; let nextCoinSlots = [...coinSlots]; const messages: string[] = []; for (const effect of effects) { if (effect.type === "health") { const before = nextHealth; nextHealth = clamp(nextHealth + effect.amount, 0, hero.maxHealth); const delta = nextHealth - before; messages.push(delta === 0 ? "Health did not change." : `Health ${delta > 0 ? "+" : ""}${delta} → ${nextHealth}/${hero.maxHealth}`); } else if (effect.type === "armor") { const before = nextArmor; nextArmor = clamp(nextArmor + effect.amount, 0, hero.maxArmor); const delta = nextArmor - before; messages.push(delta === 0 ? "Armor did not change." : `Armor ${delta > 0 ? "+" : ""}${delta} → ${nextArmor}/${hero.maxArmor}`); } else if (effect.type === "attackDice") { const before = nextAttackDice; nextAttackDice = clamp(nextAttackDice + effect.amount, 0, hero.maxAttackDice); const delta = nextAttackDice - before; messages.push(delta === 0 ? "Attack Dice did not change." : `Attack Dice ${delta > 0 ? "+" : ""}${delta} → ${nextAttackDice}/${hero.maxAttackDice}`); } else if (effect.type === "coins") { const result = adjustCoinSlots(nextCoinSlots, nextBackpack, effect.amount); nextCoinSlots = result.slots; if (result.overflow > 0) messages.push(`Backpack full: ${result.overflow} Coin${result.overflow === 1 ? "" : "s"} could not fit.`); messages.push(`Coins ${result.applied > 0 ? "+" : ""}${result.applied} → ${totalCoins(nextCoinSlots)}`); } else if (effect.type === "token") { nextTokens = { ...nextTokens, [effect.token]: Math.max(0, nextTokens[effect.token] + effect.amount) }; messages.push(`${TOKEN_LABELS[effect.token]} ${effect.amount > 0 ? "+" : ""}${effect.amount} → ${nextTokens[effect.token]}`); } else if (effect.type === "discardLoot") { for (let index = 0; index < effect.count; index += 1) { const slot = nextBackpack.findIndex(Boolean); if (slot >= 0) { const discarded = nextBackpack[slot] as FableCard; nextBackpack[slot] = null; setLootDiscard((current) => [...current, discarded]); messages.push(`Discarded ${discarded.title}.`); } } } else if (effect.type === "drawLoot") { if (run) { const drawn = await drawLootCards(run.run_id, effect.count); if (drawn.length) messages.push(`Drew ${drawn.map((card) => card.title).join(", ")}.`); } } else if (effect.type === "scout") { setScoutRemaining((current) => current + effect.count); messages.push(`Reveal ${effect.count} unexplored Location${effect.count === 1 ? "" : "s"}.`); } else if (effect.type === "resetRealm") { if (run) { const [, cell = selectedCell ?? map?.start_cell ?? ""] = sourceKey.split(":"); const result = await postJson<{ revealed: string[] }>("/api/fablefury/reset-realm", { runId: run.run_id, realm, currentCell: cell }); setRevealed((current) => ({ ...current, [realm]: result.revealed })); setScoutedByCell((current) => Object.fromEntries(Object.entries(current).filter(([key]) => !key.startsWith(`${realm}:`)))); messages.push("The Realm was scrambled back to Unexplored."); } } else if (effect.type === "note") messages.push(effect.text); }
    setHealth(nextHealth); setArmor(nextArmor); setAttackDice(nextAttackDice); setCoinSlots(nextCoinSlots); setTokens(nextTokens); setBackpack(nextBackpack); return messages; }

  function markEncounterResolved(key: string, messages: string[], roll?: number, pick?: number) { setResolvedEncounterKeys((current) => current.includes(key) ? current : [...current, key]); setEncounterHistory((current) => ({ ...current, [key]: messages })); setEventState((current) => current ? { ...current, status: "resolved", messages, roll, pick, rollMode: undefined } : current); }
  async function prepareEncounter(card: FableCard, key: string) { const plan = getEventPlan(card.id, eventContext()); if (resolvedEncounterKeys.includes(key)) { setEventState({ key, plan, status: "resolved", messages: encounterHistory[key] ?? ["This Location has already been resolved."] }); return; } if (plan.kind === "auto") { setEventState({ key, plan, status: "resolving", messages: [] }); const messages = await applyEffects(plan.effects, key); markEncounterResolved(key, messages); return; } setEventState({ key, plan, status: "pending", messages: [] }); }
  async function resolveEventEffects(effects: EventEffect[], roll?: number, pick?: number) { if (!eventState) return; setLoading("event"); setEventState((current) => current ? { ...current, status: "resolving" } : current); try { const messages = await applyEffects(effects, eventState.key); markEncounterResolved(eventState.key, messages, roll, pick); } catch (err) { setError(err instanceof Error ? err.message : "Could not resolve encounter."); setEventState((current) => current ? { ...current, status: "pending" } : current); } finally { setLoading(null); } }
  function stageEventRoll(mode: RollMode) { const roll = Math.floor(Math.random() * 6) + 1; setEventState((current) => current ? { ...current, roll, rollMode: mode } : current); }
  async function acceptEventRoll() { if (!eventState || eventState.status !== "pending" || typeof eventState.roll !== "number") return; const roll = eventState.roll; const plan = eventState.plan; if (plan.kind === "roll") await resolveEventEffects(plan.resolve(roll), roll); else if (plan.kind === "pickNumber" && eventState.pick) await resolveEventEffects(plan.resolve(eventState.pick, roll), roll, eventState.pick); else if (plan.kind === "optionalRoll") await resolveEventEffects([...plan.cost, ...plan.resolve(roll)], roll); }
  async function skipOptionalRoll() { if (!eventState || eventState.status !== "pending" || eventState.plan.kind !== "optionalRoll") return; await resolveEventEffects(eventState.plan.skipEffects ?? []); }

  async function startSkillChoices(color: SkillColor, draft: Omit<SkillDraft, "color" | "choices" | "stage">) { setLoading("skill-draw"); try { const choices = await drawSkillCards(color, 3); setSkillDraft({ ...draft, color, choices, stage: "choices" }); } catch (err) { setError(err instanceof Error ? err.message : "Could not draw Skills."); } finally { setLoading(null); } }
  async function prepareShrine(card: FableCard, key: string) { if (resolvedSpecialKeys.includes(key)) return; if (shrineStartedKeys.includes(key)) return; setShrineStartedKeys((current) => [...current, key]); const messages: string[] = []; const healed = Math.min(1, hero.maxHealth - health); setHealth((current) => Math.min(hero.maxHealth, current + 1)); messages.push(healed > 0 ? `Shrine: +1 Health → ${Math.min(hero.maxHealth, health + 1)}/${hero.maxHealth}` : "Shrine: already at full Health."); if (card.id === "special-dragon-sanctuary") { const result = adjustCoinSlots(coinSlots, backpack, 1); setCoinSlots(result.slots); messages.push(result.applied ? "Dragon Rune: +1 Coin." : "Dragon Rune Coin could not fit in the Backpack."); } else if (card.id === "special-giant-monolith") { setTokens((current) => ({ ...current, crystal: current.crystal + 1 })); messages.push("Giant Rune: +1 Crystal Ball."); } else if (card.id === "special-orc-temple") { setTokens((current) => ({ ...current, lucky: current.lucky + 1 })); messages.push("Orc Rune: +1 Lucky Charm."); }
    if (hero.id === "hero-raven-madison" && run) { const drawn = await drawLootCards(run.run_id, 1); if (drawn.length) messages.push(`Loot Lust: drew ${drawn[0].title}.`); }
    setSpecialHistory((current) => ({ ...current, [key]: messages })); const color = hero.skillSlots[realm - 1]; await startSkillChoices(color, { mode: "shrine", sourceKey: key, title: `Realm ${realm} Shrine · choose your ${color} Skill` }); }

  async function chooseSkill(card: FableCard) { if (!skillDraft) return; if (skillDraft.mode === "shrine") { const slot = realm - 1; setSkills((current) => current.map((item, index) => index === slot ? card : item)); if (skillDraft.sourceKey) setResolvedSpecialKeys((current) => current.includes(skillDraft.sourceKey as string) ? current : [...current, skillDraft.sourceKey as string]); notify(`${card.title} added as your Realm ${realm} Skill.`); setSkillDraft(null); return; } if (typeof skillDraft.slot === "number") { const replaced = skills[skillDraft.slot]; setSkills((current) => current.map((item, index) => index === skillDraft.slot ? card : item)); notify(`${replaced?.title ?? "Skill"} replaced with ${card.title}.`); setSkillDraft(null); } }
  function beginSkillReplacement(color: SkillColor | "any") { setSkillDraft({ mode: "replace", color, choices: [], title: "Replace a Skill", stage: "slot" }); }
  async function pickReplacementSlot(slot: number) { if (!skillDraft || skillDraft.mode !== "replace") return; if (skillDraft.color === "any") { setSkillDraft({ ...skillDraft, slot, stage: "color" }); return; } await startSkillChoices(skillDraft.color, { mode: "replace", slot, title: `Replace ${skills[slot]?.title ?? "Skill"} with ${skillDraft.color}` }); }
  async function pickReplacementColor(color: SkillColor) { if (!skillDraft || skillDraft.mode !== "replace" || typeof skillDraft.slot !== "number") return; await startSkillChoices(color, { mode: "replace", slot: skillDraft.slot, title: `Replace ${skills[skillDraft.slot]?.title ?? "Skill"} with ${color}` }); }

  async function applyLootEffects(use: LootUse, effects: LootEffect[]) { let nextHealth = health; let nextArmor = armor; let nextAttackDice = attackDice; let nextBackpack = backpack.map((card, index) => index === use.slot ? null : card); let nextCoinSlots = [...coinSlots]; let nextMods = { ...combatMods }; let recovered: FableCard | null = null; let dodgeTrap = false; let replacement: SkillColor | "any" | null = null; const messages: string[] = [];
    for (const effect of effects) {
      if (effect.type === "health") { const before = nextHealth; nextHealth = clamp(nextHealth + effect.amount, 0, hero.maxHealth); messages.push(`Health ${nextHealth - before >= 0 ? "+" : ""}${nextHealth - before} → ${nextHealth}/${hero.maxHealth}`); }
      else if (effect.type === "armor") { const before = nextArmor; nextArmor = clamp(nextArmor + effect.amount, 0, hero.maxArmor); messages.push(`Armor ${nextArmor - before >= 0 ? "+" : ""}${nextArmor - before} → ${nextArmor}/${hero.maxArmor}`); }
      else if (effect.type === "attackDice") { const before = nextAttackDice; nextAttackDice = clamp(nextAttackDice + effect.amount, 0, hero.maxAttackDice); messages.push(`Attack Dice ${nextAttackDice - before >= 0 ? "+" : ""}${nextAttackDice - before} → ${nextAttackDice}/${hero.maxAttackDice}`); }
      else if (effect.type === "coins") { const amount = effect.amount === "all" ? -totalCoins(nextCoinSlots) : effect.amount; const result = adjustCoinSlots(nextCoinSlots, nextBackpack, amount); nextCoinSlots = result.slots; messages.push(`Coins ${result.applied > 0 ? "+" : ""}${result.applied} → ${totalCoins(nextCoinSlots)}`); }
      else if (effect.type === "scout") { setScoutRemaining((current) => current + effect.count); messages.push(`Reveal ${effect.count} unexplored Location${effect.count === 1 ? "" : "s"}.`); }
      else if (effect.type === "damage") { setQueuedDamage((current) => [...current, { source: use.card.title, amount: effect.amount, targetRace: effect.targetRace, targetRaceAmount: effect.targetRaceAmount, everyone: effect.everyone }]); messages.push(`${use.card.title} damage armed for the next valid Enemy target.`); }
      else if (effect.type === "rerollCore") { if (pendingRoll) { const roll = Math.floor(Math.random() * 6) + 1; setEventState((current) => current ? { ...current, roll } : current); messages.push(`Core Die rerolled to ${roll}.`); } else { nextMods.rerollAttack = true; messages.push("Attack reroll armed for the next combat roll."); } }
      else if (effect.type === "increaseCore") { if (pendingRoll) { setEventState((current) => current && typeof current.roll === "number" ? { ...current, roll: Math.min(6, current.roll + effect.amount) } : current); messages.push(`Current die increased by ${effect.amount}.`); } }
      else if (effect.type === "dodgeTrap") dodgeTrap = true;
      else if (effect.type === "attackDiceThisTurn") { nextMods.attackDiceBonus += effect.amount; messages.push(`Next attack: +${effect.amount} Attack Dice.`); }
      else if (effect.type === "attackRollBonus") { nextMods.attackRollBonus += effect.amount; messages.push(`Next attack: every die +${effect.amount}.`); }
      else if (effect.type === "rerollAttack") { nextMods.rerollAttack = true; messages.push("Next missed attack dice may be rerolled."); }
      else if (effect.type === "targeting") { nextMods.targeting = effect.mode; messages.push(effect.mode === "self" ? "Next Targeted Attack is redirected to you." : "Next Targeted Attack can target any Hero."); }
      else if (effect.type === "enemyStat") { if (effect.stat === "damage") nextMods.enemyDamageDelta += effect.amount; else nextMods.enemyAgilityDelta += effect.amount; messages.push(`Next Enemy ${effect.stat} ${effect.amount}.`); }
      else if (effect.type === "rewardBonus") { nextMods.rewardBonus += effect.amount; messages.push(`Next reward +${effect.amount}.`); }
      else if (effect.type === "recoverLoot") { recovered = lootDiscard[lootDiscard.length - 1] ?? null; if (recovered) { nextBackpack[use.slot] = recovered; setLootDiscard((current) => current.slice(0, -1)); messages.push(`Recovered ${recovered.title} from the top of the Loot discard pile.`); } else messages.push("The Loot discard pile is empty."); }
      else if (effect.type === "replaceSkill") replacement = effect.color;
      else if (effect.type === "note") messages.push(effect.text);
    }
    setHealth(nextHealth); setArmor(nextArmor); setAttackDice(nextAttackDice); setCoinSlots(nextCoinSlots); setBackpack(nextBackpack); setCombatMods(nextMods); if (use.card.id !== "loot-gum-string" || !recovered) setLootDiscard((current) => [...current, use.card]); else setLootDiscard((current) => [...current, use.card]);
    if (dodgeTrap && eventState?.status === "pending" && selectedCard?.data?.digital_card_type === "trap") markEncounterResolved(eventState.key, [`${use.card.title} dodges the Trap. No damage taken.`]);
    else if (eventState?.status === "pending" && selectedCard?.data?.digital_card_type === "trap") setEventState((current) => current ? { ...current, plan: getEventPlan(selectedCard.id, eventContext({ health: nextHealth, armor: nextArmor, attackDice: nextAttackDice, coins: totalCoins(nextCoinSlots), backpack: nextBackpack })) } : current);
    setLootUse(null); if (replacement) beginSkillReplacement(replacement); notify(messages[0] ?? `${use.card.title} used.`); }

  async function revealLocation(cell: string) { if (!run || !map || phase !== "realm") return; const cellKey = `${realm}:${cell}`; if (scoutRemaining > 0 && !realmRevealed.includes(cell)) { setLoading(`peek-${cellKey}`); setError(null); try { const result = await postJson<{ cell: string; card: FableCard }>("/api/fablefury/peek", { runId: run.run_id, realm, cell }); setScoutedByCell((current) => ({ ...current, [cellKey]: result.card })); setScoutRemaining((current) => Math.max(0, current - 1)); setSelectedCard(result.card); setSelectedCell(cell); setEventState(null); setShowReveal(true); } catch (err) { setError(err instanceof Error ? err.message : "Could not reveal that Location."); } finally { setLoading(null); } return; }
    if (inventoryLocked || encounterLocked || scoutRemaining > 0) return; const existing = cardsByCell[cellKey]; if (realmRevealed.includes(cell) && existing) { setSelectedCard(existing); setSelectedCell(cell); setShowReveal(true); if (existing.card_type === "event") await prepareEncounter(existing, cellKey); else if (existing.card_type === "special" && existing.subtype === "shrine") await prepareShrine(existing, cellKey); else setEventState(null); return; }
    const allowed = realmRevealed.length === 0 ? cell === map.start_cell : realmRevealed.some((seenCell) => isAdjacent(seenCell, cell)); if (!allowed) return; setLoading(`cell-${cellKey}`); setError(null); try { const result = await postJson<RevealResult>("/api/fablefury/reveal", { runId: run.run_id, realm, cell }); setRevealed((current) => ({ ...current, [realm]: result.revealed })); setCardsByCell((current) => ({ ...current, [cellKey]: result.card })); setSelectedCard(result.card); setSelectedCell(cell); setShowReveal(true); if (result.card.card_type === "event") await prepareEncounter(result.card, cellKey); else if (result.card.card_type === "special" && result.card.subtype === "shrine") await prepareShrine(result.card, cellKey); else setEventState(null); } catch (err) { setError(err instanceof Error ? err.message : "Could not reveal location."); } finally { setLoading(null); } }

  function closeReveal() { if (eventState && eventState.status !== "resolved") return; if (shrinePending) return; setShowReveal(false); setSelectedCard(null); setSelectedCell(null); setEventState(null); }

  function renderEncounterControls() { if (!eventState) return null; const plan = eventState.plan; if (eventState.status === "resolving") return <div className="rounded-2xl border border-amber-300/20 bg-amber-300/10 p-4 text-sm font-bold text-amber-100">Resolving…</div>; if (eventState.status === "resolved") return <div><div className="flex flex-wrap items-center gap-2">{typeof eventState.roll === "number" && <div className="grid h-14 w-14 place-items-center rounded-2xl border border-amber-300/40 bg-amber-300/10 text-2xl font-black text-amber-100">{eventState.roll}</div>}<div className="text-[10px] font-black uppercase tracking-[.14em] text-emerald-300">Resolved</div></div><div className="mt-4 grid gap-2">{eventState.messages.map((message, index) => <div key={`${message}-${index}`} className="rounded-xl border border-white/[.07] bg-black/20 px-3 py-2 text-xs leading-5 text-white/65">{message}</div>)}</div><button type="button" onClick={closeReveal} className="mt-4 w-full rounded-2xl bg-amber-300 px-5 py-3 text-sm font-black text-[#241707]">Continue</button></div>;
    if (typeof eventState.roll === "number") return <div><div className="flex items-center gap-4 rounded-2xl border border-amber-300/25 bg-amber-300/10 p-4"><img src={FABLE_STAT_ART.attackDice} alt="Core die" className="h-14 w-14 object-contain" /><div><div className="text-[10px] font-black uppercase tracking-[.15em] text-amber-200">Core Roll</div><div className="text-4xl font-black text-[#fff4d8]">{eventState.roll}</div></div></div><p className="mt-3 text-xs leading-5 text-white/50">Accept it, use a Lucky Charm, Rabbit's Foot, Foghorn, or any other relevant Loot before resolving.</p><div className="mt-3 grid gap-2 sm:grid-cols-2"><TokenAction token="lucky" count={tokens.lucky} onUse={() => useToken("lucky")} /><button type="button" onClick={acceptEventRoll} disabled={loading === "event"} className="rounded-2xl bg-amber-300 px-5 py-3 text-sm font-black text-[#241707]">Accept {eventState.roll} →</button></div></div>;
    if (plan.kind === "choice") return <div><div className="mb-3 text-sm font-bold text-white/75">{plan.prompt}</div><div className="grid gap-2">{plan.options.map((option) => { const enabled = requirementMet(option.requires, eventContext()); return <button key={option.label} type="button" disabled={!enabled || loading === "event"} onClick={() => resolveEventEffects(option.effects)} className="rounded-2xl border border-white/10 bg-white/[.05] px-4 py-3 text-left hover:border-amber-300/40 disabled:opacity-35"><strong className="text-sm text-[#fff4d8]">{option.label}</strong>{option.description && <span className="mt-1 block text-xs leading-5 text-white/45">{option.description}</span>}</button>; })}</div></div>;
    if (plan.kind === "roll") return <div><p className="text-sm font-bold leading-6 text-white/70">{plan.prompt}</p><button type="button" onClick={() => stageEventRoll("roll")} className="mt-4 w-full rounded-2xl bg-amber-300 px-5 py-4 text-sm font-black text-[#241707]">Roll Core Die</button></div>;
    if (plan.kind === "pickNumber") return <div><p className="text-sm font-bold leading-6 text-white/70">{plan.prompt}</p><div className="mt-4 grid grid-cols-6 gap-2">{[1,2,3,4,5,6].map((value) => <button key={value} type="button" onClick={() => setEventState((current) => current ? { ...current, pick: value } : current)} className={`aspect-square rounded-xl border text-sm font-black ${eventState.pick === value ? "border-amber-300 bg-amber-300 text-[#241707]" : "border-white/10 bg-white/5 text-white/70"}`}>{value}</button>)}</div><button type="button" onClick={() => stageEventRoll("pickNumber")} disabled={!eventState.pick} className="mt-3 w-full rounded-2xl bg-amber-300 px-5 py-4 text-sm font-black text-[#241707] disabled:opacity-35">Roll Core Die</button></div>;
    if (plan.kind === "optionalRoll") { const canPay = requirementMet(plan.requires, eventContext()); return <div><p className="text-sm font-bold leading-6 text-white/70">{plan.prompt}</p><div className="mt-4 grid gap-2 sm:grid-cols-2"><button type="button" disabled={!canPay} onClick={() => stageEventRoll("optionalRoll")} className="rounded-2xl bg-amber-300 px-4 py-3 text-sm font-black text-[#241707] disabled:opacity-35">{plan.payLabel}</button><button type="button" onClick={skipOptionalRoll} className="rounded-2xl border border-white/10 bg-white/5 px-4 py-3 text-sm font-black text-white/70">{plan.skipLabel}</button></div></div>; }
    return null; }

  function renderSpecialControls() { if (!selectedCard || selectedCard.card_type !== "special") return null; const key = selectedCell ? `${realm}:${selectedCell}` : ""; if (selectedCard.subtype === "shrine") { const messages = specialHistory[key] ?? []; if (resolvedSpecialKeys.includes(key)) return <div><div className="text-[10px] font-black uppercase tracking-[.14em] text-emerald-300">Shrine Cleared</div><div className="mt-3 grid gap-2">{messages.map((message, index) => <div key={index} className="rounded-xl border border-white/[.07] bg-black/20 px-3 py-2 text-xs text-white/65">{message}</div>)}</div><button type="button" onClick={closeReveal} className="mt-4 w-full rounded-2xl bg-amber-300 px-5 py-3 text-sm font-black text-[#241707]">Continue</button></div>; return <div><div className="text-[10px] font-black uppercase tracking-[.14em] text-violet-300">Shrine resolving</div><div className="mt-3 grid gap-2">{messages.map((message, index) => <div key={index} className="rounded-xl border border-white/[.07] bg-black/20 px-3 py-2 text-xs text-white/65">{message}</div>)}</div><p className="mt-3 text-xs leading-5 text-white/50">Your Realm {realm} Skill is the <strong className="text-white/80">{hero.skillSlots[realm - 1]}</strong> slot on {hero.name}'s mat. Draw 3, choose 1.</p></div>; }
    return <div><div className="rounded-xl border border-violet-300/20 bg-violet-400/10 p-3 text-xs leading-5 text-violet-100">Portal resolution comes next. This Portal remains locked to the board.</div><button type="button" onClick={closeReveal} className="mt-4 w-full rounded-2xl bg-amber-300 px-5 py-3 text-sm font-black text-[#241707]">Continue</button></div>; }

  const selectedBack = selectedCard?.card_type === "loot" ? FABLE_CARD_BACKS.loot : FABLE_CARD_BACKS.location;
  const lootPlan = lootUse ? getLootPlan(lootUse.card.id, lootContext()) : null;
  const armedCount = queuedDamage.length + Object.values(combatMods).filter((value) => typeof value === "number" ? value !== 0 : Boolean(value)).length;

  return <main className="min-h-screen bg-[#0b1017] px-4 py-6 text-[#f8f0dc] md:px-8 lg:px-10"><div className="mx-auto max-w-[1740px]"><header className="flex flex-col gap-4 border-b border-white/10 pb-5 md:flex-row md:items-end md:justify-between"><div><div className="text-[10px] font-black uppercase tracking-[.2em] text-amber-300">Fable Fury · Solo Adventure Prototype</div><h1 className="mt-1 text-4xl font-black tracking-[-.05em] md:text-6xl">{phase === "hero" ? "Choose Your Hero" : phase === "gear" ? "Pack Your Bag" : `Realm ${realm}`}</h1><p className="mt-2 max-w-3xl text-sm leading-6 text-white/50">{phase === "hero" ? "Lock in one Hero and one starting Token." : phase === "gear" ? "Coins and Loot share the three lower Backpack pockets." : "Explore the real board. Events, Traps, Loot and Shrines now resolve against your live Hero state."}</p></div><div className="flex flex-wrap gap-2"><a href="/fablefury/deckbuilder" className="rounded-xl border border-white/10 bg-white/5 px-4 py-3 text-xs font-bold text-white/65">Hero Lab</a>{phase !== "hero" && <button type="button" onClick={resetAdventure} className="rounded-xl border border-white/10 bg-white/5 px-4 py-3 text-xs font-bold text-white/65">New Adventure</button>}</div></header>{error && <div className="mt-5 rounded-xl border border-red-400/30 bg-red-500/10 px-4 py-3 text-sm text-red-100">{error}</div>}

  {phase === "hero" && <section className="mt-7"><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{FABLE_HEROES.map((candidate) => { const active = candidate.id === heroId; return <button key={candidate.id} type="button" onClick={() => setHeroId(candidate.id)} className={`overflow-hidden rounded-[26px] border text-left transition ${active ? "border-amber-300/70 bg-amber-300/10" : "border-white/10 bg-white/[.035] hover:border-white/20"}`}><div className="aspect-[1.52/1] overflow-hidden bg-black/20"><img src={candidate.mat} alt={`${candidate.name} hero mat`} className="h-full w-full object-cover" /></div><div className="p-4"><div className="text-[9px] font-black uppercase tracking-[.15em] text-amber-300">{candidate.role} · {candidate.race}</div><div className="mt-1 text-xl font-black">{candidate.name}</div><div className="mt-3 flex flex-wrap gap-3 text-[10px] text-white/55"><MiniStat art={FABLE_STAT_ART.health} value={candidate.startingHealth} /><MiniStat art={FABLE_STAT_ART.armor} value={candidate.startingArmor} /><MiniStat art={FABLE_STAT_ART.attackDice} value={candidate.startingAttackDice} /></div><div className="mt-3 text-[10px] font-black uppercase tracking-[.12em] text-white/35">Shrine Skills: {candidate.skillSlots.join(" → ")}</div></div></button>; })}</div><div className="mt-6 rounded-[26px] border border-white/10 bg-white/[.035] p-5"><div className="text-[10px] font-black uppercase tracking-[.16em] text-amber-300">Starting Token · choose 1</div><div className="mt-4 grid gap-3 sm:grid-cols-3">{(["healing","lucky","crystal"] as TokenKind[]).map((token) => <button key={token} type="button" onClick={() => setStartingToken(token)} className={`flex items-center gap-4 rounded-2xl border p-4 text-left ${startingToken === token ? "border-amber-300 bg-amber-300/10" : "border-white/10 bg-black/20"}`}><img src={FABLE_TOKEN_ART[token]} alt={TOKEN_LABELS[token]} className="h-16 w-16 object-contain" /><strong>{TOKEN_LABELS[token]}</strong></button>)}</div><button type="button" onClick={lockHeroAndDeal} disabled={!startingToken || loading === "setup"} className="mt-5 w-full rounded-2xl bg-amber-300 px-6 py-4 text-sm font-black text-[#241707] disabled:opacity-35">{loading === "setup" ? "Building Run…" : "Lock Hero & Deal Gear →"}</button></div></section>}

  {phase === "gear" && run && <section className="mt-7 grid gap-5 xl:grid-cols-[.9fr_1.1fr]"><div className="grid content-start gap-4"><div className="rounded-[28px] border border-white/10 bg-white/[.035] p-5"><img src={hero.mat} alt={`${hero.name} hero mat`} className="w-full rounded-[22px]" /><div className="mt-4 grid grid-cols-2 gap-2 sm:grid-cols-4"><StatPill art={FABLE_STAT_ART.health} label="Health" value={health} max={hero.maxHealth} /><StatPill art={FABLE_STAT_ART.armor} label="Armor" value={armor} max={hero.maxArmor} /><StatPill art={FABLE_STAT_ART.attackDice} label="Attack Dice" value={attackDice} max={hero.maxAttackDice} /><StatPill art={FABLE_STAT_ART.coins} label="Coins" value={coins} /></div></div><BackpackPanel backpack={backpack} coinSlots={coinSlots} tokens={tokens} onUseToken={useToken} onUseLoot={(slot) => backpack[slot] && setLootUse({ slot, card: backpack[slot] as FableCard })} luckyDisabled crystalDisabled /></div><div className="rounded-[28px] border border-white/10 bg-white/[.035] p-5"><div className="text-[10px] font-black uppercase tracking-[.16em] text-amber-300">Starting Loot Draw</div>{lootInbox[0] ? <div className="mt-4 grid gap-5 sm:grid-cols-[210px_1fr]"><CardImage card={lootInbox[0]} className="w-full rounded-2xl" /><div><h2 className="text-2xl font-black">{lootInbox[0].title}</h2><p className="mt-2 text-sm leading-6 text-white/55">{lootInbox[0].rules_text}</p><div className="mt-4 grid gap-2">{backpack.map((slotCard, slot) => <button key={slot} type="button" disabled={coinSlots[slot] > 0 || Boolean(slotCard)} onClick={() => packLoot(0, slot)} className="rounded-xl border border-amber-300/25 bg-amber-300/10 px-4 py-3 text-left text-xs font-black disabled:opacity-35">Pocket {slot + 1}: {coinSlots[slot] > 0 ? `${coinSlots[slot]} Coins` : slotCard?.title ?? "Empty"}</button>)}</div></div></div> : <div className="mt-4 rounded-2xl border border-emerald-300/20 bg-emerald-300/10 p-5 text-sm text-emerald-100">Starting gear packed.</div>}<button type="button" disabled={lootInbox.length > 0} onClick={() => setPhase("realm")} className="mt-6 w-full rounded-2xl bg-amber-300 px-6 py-4 text-sm font-black text-[#241707] disabled:opacity-30">Enter Realm 1 →</button></div></section>}

  {phase === "realm" && run && map && <section className="mt-5 grid gap-4 2xl:grid-cols-[350px_minmax(760px,1fr)_300px]"><aside className="grid content-start gap-4"><div className="rounded-[24px] border border-white/10 bg-white/[.035] p-4"><img src={hero.mat} alt={`${hero.name} hero mat`} className="w-full rounded-2xl" /><div className="mt-3 text-lg font-black">{hero.name}</div><div className="mt-3 grid grid-cols-2 gap-2"><StatPill art={FABLE_STAT_ART.health} label="Health" value={health} max={hero.maxHealth} /><StatPill art={FABLE_STAT_ART.armor} label="Armor" value={armor} max={hero.maxArmor} /><StatPill art={FABLE_STAT_ART.attackDice} label="Attack Dice" value={attackDice} max={hero.maxAttackDice} /><StatPill art={FABLE_STAT_ART.coins} label="Coins" value={coins} /></div><div className="mt-3 grid grid-cols-3 gap-2">{hero.skillSlots.map((color, index) => <div key={index} className="rounded-xl border border-white/10 bg-black/20 p-2"><div className="text-[8px] font-black uppercase text-white/35">R{index + 1} · {color}</div>{skills[index] ? <CardImage card={skills[index] as FableCard} className="mt-2 w-full rounded-md" /> : <div className="mt-2 grid aspect-[.72] place-items-center rounded-md border border-dashed border-white/10 text-[8px] text-white/25">Empty</div>}</div>)}</div></div><BackpackPanel backpack={backpack} coinSlots={coinSlots} tokens={tokens} onUseToken={useToken} onUseLoot={(slot) => backpack[slot] && setLootUse({ slot, card: backpack[slot] as FableCard })} luckyDisabled={!pendingRoll} crystalDisabled={false} />{armedCount > 0 && <div className="rounded-[24px] border border-fuchsia-300/20 bg-fuchsia-300/[.05] p-4"><div className="text-[9px] font-black uppercase tracking-[.14em] text-fuchsia-300">Armed Loot effects</div><p className="mt-2 text-xs leading-5 text-white/50">{queuedDamage.length} queued damage effect{queuedDamage.length === 1 ? "" : "s"}. Combat modifiers are stored for the Enemy system we wire next.</p></div>}</aside>
    <section className="rounded-[28px] border border-white/10 bg-white/[.035] p-3 md:p-4"><div className="flex flex-wrap items-end justify-between gap-3 px-1 pb-3"><div><div className="text-[9px] font-black uppercase tracking-[.15em] text-white/35">Game board · Realm {realm}</div><h2 className="mt-1 text-2xl font-black">{map.name}</h2><p className="mt-1 text-xs text-white/40">{remainingLocations} unexplored · Start {map.start_cell}</p></div><div className="flex gap-2">{[1,2,3].map((value) => <button key={value} type="button" onClick={() => { if (!encounterLocked && !inventoryLocked && scoutRemaining === 0) { setRealm(value); setSelectedCard(null); setShowReveal(false); setEventState(null); } }} className={`rounded-xl px-3 py-2 text-[10px] font-black ${realm === value ? "bg-amber-300 text-[#241707]" : "border border-white/10 bg-white/5 text-white/50"}`}>R{value}</button>)}</div></div>{scoutRemaining > 0 && <div className="mb-3 rounded-2xl border border-violet-300/35 bg-violet-400/10 px-4 py-3 text-xs font-bold text-violet-100">Reveal mode: choose {scoutRemaining} unexplored Location{scoutRemaining === 1 ? "" : "s"}.</div>}{inventoryLocked && <div className="mb-3 rounded-2xl border border-amber-300/30 bg-amber-300/10 px-4 py-3 text-xs font-bold text-amber-100">Pack or discard your waiting Loot before travelling.</div>}<div className="flex justify-center overflow-hidden rounded-[24px] border border-white/10 bg-black/30 p-1"><div className="relative w-full max-w-[1040px]"><img src={FABLE_BOARD_ART} alt="Fable Fury game board" className="block w-full" /><div className="absolute left-[16.5%] top-[6.7%] z-10 w-[7.2%] -translate-x-1/2 -translate-y-1/2"><div className="relative aspect-[746/1039]"><img src={FABLE_CARD_BACKS.loot} alt="Loot deck" className="h-full w-full rounded-[7px] object-cover" /><span className="absolute -right-2 -top-2 grid h-6 min-w-6 place-items-center rounded-full bg-amber-300 px-1 text-[10px] font-black text-[#241707]">{lootRemaining}</span></div></div><img src={FABLE_SHOP_ART.crystal} alt="Crystal Ball supply" className="absolute left-[6.8%] top-[17.4%] z-10 w-[4.5%] -translate-x-1/2 -translate-y-1/2 object-contain" /><img src={FABLE_SHOP_ART.lucky} alt="Lucky Charm supply" className="absolute left-[12.2%] top-[17.4%] z-10 w-[4.5%] -translate-x-1/2 -translate-y-1/2 object-contain" /><img src={FABLE_SHOP_ART.healing} alt="Healing Potion supply" className="absolute left-[17.6%] top-[17.4%] z-10 w-[4.5%] -translate-x-1/2 -translate-y-1/2 object-contain" />{map.grid.active_cells.map((cell) => { const key = `${realm}:${cell}`; const explored = realmRevealed.includes(cell); const card = cardsByCell[key]; const scouted = scoutedByCell[key]; const normallyReachable = realmRevealed.length === 0 ? cell === map.start_cell : realmRevealed.some((prior) => isAdjacent(prior, cell)); const clickable = scoutRemaining > 0 ? !explored : (!inventoryLocked && !encounterLocked && (explored || normallyReachable)); const artCard = explored ? card : scouted; return <button key={cell} type="button" onClick={() => revealLocation(cell)} disabled={!clickable || loading === `cell-${key}` || loading === `peek-${key}`} className={`absolute w-[9.15%] -translate-x-1/2 -translate-y-1/2 overflow-hidden rounded-[8px] border shadow-xl transition ${explored ? "z-30 border-amber-200/75" : scouted ? "z-20 border-violet-300/75" : clickable ? "z-20 border-amber-200/65 hover:scale-110" : "z-20 border-white/10 opacity-42"}`} style={boardCellPosition(cell)}><div className="relative aspect-[746/1039] bg-[#202936]">{artCard ? <CardImage card={artCard} className="h-full w-full" /> : <img src={FABLE_CARD_BACKS.location} alt="Unexplored Location" className="h-full w-full object-cover" />}<span className="absolute left-1 top-1 rounded-full bg-black/60 px-1.5 py-0.5 text-[7px] font-black">{cell}</span>{cell === map.start_cell && <span className="absolute right-1 top-1 rounded-full bg-amber-300 px-1.5 py-0.5 text-[6px] font-black text-[#241707]">START</span>}</div></button>; })}</div></div></section>
    <aside className="grid content-start gap-4"><div className="rounded-[24px] border border-white/10 bg-white/[.035] p-4"><div className="text-[9px] font-black uppercase tracking-[.14em] text-amber-300">Current Map Card</div>{mapImage && <img src={mapImage} alt={`${map.name} map card`} className="mt-3 w-full rounded-2xl border border-white/10" />}</div>{lootInbox.length > 0 && <div className="rounded-[24px] border border-amber-300/30 bg-amber-300/[.07] p-4"><div className="text-[9px] font-black uppercase tracking-[.14em] text-amber-200">Loot waiting · {lootInbox.length}</div><div className="mt-3 grid gap-4">{lootInbox.map((card, inboxIndex) => <div key={`${card.id}-${inboxIndex}`} className="grid grid-cols-[82px_1fr] gap-3"><CardImage card={card} className="w-full rounded-lg" /><div><strong className="text-xs">{card.title}</strong><div className="mt-2 grid gap-1">{backpack.map((slotCard, slot) => <button key={slot} disabled={coinSlots[slot] > 0 || Boolean(slotCard)} onClick={() => packLoot(inboxIndex, slot)} className="rounded-lg border border-amber-300/20 bg-amber-300/10 px-2 py-1.5 text-left text-[9px] font-black disabled:opacity-30">Pocket {slot + 1}: {coinSlots[slot] > 0 ? `${coinSlots[slot]} Coins` : slotCard?.title ?? "Empty"}</button>)}</div><button type="button" onClick={() => discardInboxLoot(inboxIndex)} className="mt-2 text-[9px] text-white/35 underline">Discard</button></div></div>)}</div></div>}<div className="rounded-[24px] border border-white/10 bg-white/[.035] p-4"><div className="text-[9px] font-black uppercase tracking-[.14em] text-white/35">Realm state</div><p className="mt-2 text-xs leading-5 text-white/45">{REALM_RECIPES[realm]}</p><div className="mt-3 grid grid-cols-4 gap-1">{SKILL_COLORS.map((color) => <div key={color} className="rounded-lg border border-white/10 bg-black/20 px-2 py-2 text-center"><div className="text-[8px] font-black uppercase text-white/35">{color}</div><div className="text-sm font-black">{skillRemaining[color]}</div></div>)}</div></div></aside></section>}
  </div>

  {showReveal && selectedCard && <ModalShell z="z-[200]"><section className="relative grid w-full max-w-[1120px] gap-6 md:grid-cols-[minmax(260px,430px)_1fr]"><button type="button" onClick={closeReveal} disabled={(eventState && eventState.status !== "resolved") || shrinePending} className="absolute -right-1 -top-12 z-30 grid h-10 w-10 place-items-center rounded-full border border-white/15 bg-white/10 text-xl disabled:opacity-20">×</button><FlipCard card={selectedCard} back={selectedBack} /><div className="flex min-w-0 flex-col justify-center rounded-[28px] border border-white/10 bg-[#111821]/95 p-6 md:p-8"><div className="text-[10px] font-black uppercase tracking-[.2em] text-amber-300">{displayCardType(selectedCard)}{selectedCard.difficulty ? ` · ${selectedCard.difficulty}` : ""}</div><h2 className="mt-2 text-3xl font-black md:text-5xl">{selectedCard.title}</h2>{selectedCard.rules_text && <p className="mt-5 whitespace-pre-line text-sm font-semibold leading-6 text-white/75">{selectedCard.rules_text}</p>}<div className="mt-5 border-t border-white/10 pt-4"><div className="mb-2 text-[9px] font-black uppercase tracking-[.14em] text-white/35">Use Backpack items any time</div><div className="grid grid-cols-3 gap-2"><TokenAction token="healing" count={tokens.healing} onUse={() => useToken("healing")} compact /><TokenAction token="crystal" count={tokens.crystal} onUse={() => useToken("crystal")} compact /><TokenAction token="lucky" count={tokens.lucky} onUse={() => useToken("lucky")} disabled={!pendingRoll} compact /></div>{backpack.filter(Boolean).length > 0 && <div className="mt-2 grid grid-cols-3 gap-2">{backpack.map((card, slot) => card ? <button key={slot} type="button" onClick={() => setLootUse({ slot, card })} className="rounded-xl border border-white/10 bg-black/20 p-2 hover:border-amber-300/40"><CardImage card={card} className="mx-auto h-20 rounded-md" /><span className="mt-1 block truncate text-[8px] font-black">{card.title}</span></button> : <div key={slot} />)}</div>}</div><div className="mt-5 border-t border-white/10 pt-5">{selectedCard.card_type === "event" && eventState ? renderEncounterControls() : selectedCard.card_type === "special" ? renderSpecialControls() : <div>{selectedCard.card_type === "enemy" && <div className="rounded-xl border border-red-300/20 bg-red-400/10 p-3 text-xs text-red-100">Enemy combat is next. Any damage/stat Loot you use now is queued for that system.</div>}<button type="button" onClick={closeReveal} className="mt-4 w-full rounded-2xl bg-amber-300 px-5 py-3 text-sm font-black text-[#241707]">Continue</button></div>}</div></div></section></ModalShell>}

  {lootUse && lootPlan && <ModalShell z="z-[320]"><section className="grid w-full max-w-[880px] gap-5 rounded-[30px] border border-white/10 bg-[#111821] p-5 shadow-2xl md:grid-cols-[230px_1fr] md:p-7"><CardImage card={lootUse.card} className="w-full rounded-2xl" /><div><div className="text-[10px] font-black uppercase tracking-[.16em] text-amber-300">Use Loot · one time</div><h2 className="mt-1 text-3xl font-black">{lootUse.card.title}</h2><p className="mt-3 whitespace-pre-line text-sm leading-6 text-white/60">{lootUse.card.rules_text}</p>{lootPlan.prompt && <p className="mt-5 text-sm font-bold text-white/75">{lootPlan.prompt}</p>}<div className="mt-4 grid gap-2">{lootPlan.options.map((option) => { const enabled = option.requires ? option.requires(lootContext()) : true; return <button key={option.label} type="button" disabled={!enabled} onClick={() => applyLootEffects(lootUse, option.effects)} className="rounded-2xl border border-amber-300/25 bg-amber-300/10 px-4 py-4 text-left hover:border-amber-300/60 disabled:cursor-not-allowed disabled:opacity-35"><strong className="text-sm text-amber-100">{option.label}</strong>{!enabled && option.unavailableText && <span className="mt-1 block text-xs text-white/40">{option.unavailableText}</span>}</button>; })}</div><button type="button" onClick={() => setLootUse(null)} className="mt-4 w-full rounded-2xl border border-white/10 bg-white/5 px-4 py-3 text-sm font-black text-white/60">Keep it for later</button></div></section></ModalShell>}

  {skillDraft && <ModalShell z="z-[340]"><section className="w-full max-w-[1050px] rounded-[30px] border border-white/10 bg-[#111821] p-5 shadow-2xl md:p-7"><div className="text-[10px] font-black uppercase tracking-[.16em] text-violet-300">Skill choice</div><h2 className="mt-1 text-3xl font-black">{skillDraft.title}</h2>{skillDraft.stage === "slot" && <div className="mt-5 grid gap-3 sm:grid-cols-3">{skills.map((card, slot) => card ? <button key={slot} onClick={() => pickReplacementSlot(slot)} className="rounded-2xl border border-white/10 bg-black/20 p-3 text-left hover:border-violet-300/50"><CardImage card={card} className="w-full rounded-xl" /><strong className="mt-2 block text-sm">Replace {card.title}</strong></button> : null)}</div>}{skillDraft.stage === "color" && <div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-4">{SKILL_COLORS.map((color) => <button key={color} onClick={() => pickReplacementColor(color)} className="rounded-2xl border border-white/10 bg-black/20 px-5 py-8 text-lg font-black capitalize hover:border-violet-300/50">{color}</button>)}</div>}{skillDraft.stage === "choices" && <><p className="mt-3 text-sm text-white/50">Three random <strong className="text-white/80">{skillDraft.color}</strong> Skills were drawn. Choose one; the others leave this run's draw pile.</p><div className="mt-5 grid gap-4 md:grid-cols-3">{skillDraft.choices.map((card) => <button key={card.id} onClick={() => chooseSkill(card)} className="overflow-hidden rounded-2xl border border-white/10 bg-black/20 text-left transition hover:-translate-y-1 hover:border-violet-300/60"><CardImage card={card} className="w-full" /><div className="p-3"><strong className="text-sm">{card.title}</strong><p className="mt-1 text-xs leading-5 text-white/45">{card.rules_text}</p></div></button>)}</div></>}{skillDraft.mode === "replace" && <button type="button" onClick={() => setSkillDraft(null)} className="mt-5 w-full rounded-2xl border border-white/10 bg-white/5 px-4 py-3 text-sm font-black text-white/60">Cancel replacement</button>}</section></ModalShell>}

  {toast && <div className="fixed bottom-5 right-5 z-[400] max-w-sm rounded-2xl border border-amber-300/30 bg-[#17130d]/95 px-4 py-3 text-xs font-bold leading-5 text-amber-50 shadow-2xl backdrop-blur">{toast}</div>}
  </main>;
}
